import {validateMessage} from './validation.js';

it('preserves valid paging cursors and rejects malformed cursors (specs/hal-engine-conversation-list/spec.md#42)', () => {
  const cursors = [
    {sessionId: 's', updatedAt: '2026-01-01T00:00:00.000Z'},
    {sessionId: 's'.repeat(128), updatedAt: 0},
  ];
  const invalid = [
    null,
    [],
    'not-an-object',
    {},
    {sessionId: '', updatedAt: 0},
    {sessionId: 's'.repeat(129), updatedAt: 0},
    {sessionId: 1, updatedAt: 0},
    ...['not-a-date', true, null, Infinity, 9e15].map(updatedAt => ({sessionId: 's', updatedAt})),
  ];
  const request = (before: unknown) => validateMessage({type: 'list_sessions', before, userId: 'stranger'});

  expect({
    accepted: cursors.map(before => request({...before, userId: 'stranger'})),
    rejected: invalid.map(request),
  }).toEqual({
    accepted: cursors.map(before => ({valid: true, data: {type: 'list_sessions', before}})),
    rejected: invalid.map(() => ({valid: false, error: expect.stringContaining('before')})),
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/transport/ws/listSessionsCursor.test.ts --runInBand"

